window.SCHOOL_LISTENING={"../assets/media/8a51f03a204efb0c83b9e8ff6fba679f57fd2ea4c59414540ab733feb95a9d97.mp3":[{"id":"PPT_8a51f03a204efb0c","audioId":"PPT_8a51f03a204efb0c","title":"Book 2 · Unit 8 · RW · READING 2","subtitle":"READING 2 · source slide 146","duration":176.01,"cues":[{"start":0,"end":2.08,"text":"Life on other planets.","coverage":1},{"start":3.2,"end":8.3,"text":"For many years, people have wondered whether we are the only living things in the universe.","coverage":1},{"start":9.34,"end":15.8,"text":"Some scientists believe that there must be life on other planets because the universe is so big.","coverage":1},{"start":16.5,"end":16.96,"text":"However,","coverage":1},{"start":17.46,"end":24.84,"text":"it is unlikely that there is life on other planets because planets need a very specific environment for life to start.","coverage":1},{"start":25.52,"end":27.06,"text":"In the end, there are","coverage":1},{"start":27.06,"end":27.34,"text":"no","coverage":1},{"start":27.34,"end":30.72,"text":"facts that support the idea of life on other planets.","coverage":1},{"start":32.12,"end":35.6,"text":"It is true that the universe has thousands of solar systems,","coverage":1},{"start":36.02,"end":38.02,"text":"and there are planets similar to Earth.","coverage":1},{"start":38.76,"end":40.74,"text":"During its nine years in space,","coverage":1},{"start":41.2,"end":48.94,"text":"the very powerful Kepler telescope found more than two ,600 planets in orbit around stars.","coverage":1},{"start":49.66,"end":50.3,"text":"In fact,","coverage":1},{"start":50.62,"end":56.36,"text":"a number of scientists think that one of these planets, named Kepler -22b,","coverage":1},{"start":56.78,"end":58.14,"text":"has the right conditions,","coverage":1},{"start":58.58,"end":60.52,"text":"the right atmosphere and temperature,","coverage":1},{"start":60.9,"end":61.96,"text":"to support life.","coverage":1},{"start":62.78,"end":63.34,"text":"However,","coverage":1},{"start":63.68,"end":64.02,"text":"there is","coverage":1},{"start":64.02,"end":64.36,"text":"no","coverage":1},{"start":64.36,"end":67.48,"text":"evidence that there is life on Kepler -22b.","coverage":1},{"start":68.58,"end":71.78,"text":"Experts argue that even with the best technology,","coverage":1},{"start":72.16,"end":72.78,"text":"we can see","coverage":1},{"start":72.78,"end":73.1,"text":"no","coverage":1},{"start":73.1,"end":74.32,"text":"signs of life there.","coverage":1},{"start":75.04,"end":77.2,"text":"Until research shows us hard evidence,","coverage":1},{"start":77.66,"end":83.24,"text":"we cannot use Kepler -22b to support the idea of life on other planets.","coverage":1},{"start":84.2,"end":88.26,"text":"A planet needs very particular conditions to support life.","coverage":1},{"start":89.02,"end":91.22,"text":"A planet with life would need to have water,","coverage":1},{"start":91.54,"end":92.46,"text":"the right temperature,","coverage":1},{"start":93.02,"end":95.64,"text":"and the right mix of chemicals in the atmosphere.","coverage":1},{"start":96.54,"end":99.22,"text":"Earth has the perfect conditions for life,","coverage":1},{"start":99.8,"end":105.3,"text":"and it is very unlikely that another planet has exactly the same environment as Earth.","coverage":1},{"start":105.96,"end":106.98,"text":"In addition,","coverage":1},{"start":107.62,"end":114.92,"text":"although some experts argue that life might exist on other planets, they have never found evidence to prove it.","coverage":1},{"start":115.36,"end":121.92,"text":"A report from Princeton University suggests that it is highly unlikely that there is life on other planets.","coverage":1},{"start":122.68,"end":129.2,"text":"The researchers believe that we don't have enough scientific evidence to decide if there is life on other planets.","coverage":1},{"start":129.92,"end":134.9,"text":"They say that just because conditions similar to Earth exist on other planets,","coverage":1},{"start":135.48,"end":137.86,"text":"it doesn't mean that life exists there.","coverage":1},{"start":138.81,"end":139.8,"text":"In conclusion,","coverage":1},{"start":140.44,"end":143.74,"text":"I do not believe that there is life on other planets.","coverage":1},{"start":144.68,"end":146.76,"text":"Although the universe is very big,","coverage":1},{"start":147.26,"end":150.84,"text":"a planet with life needs very special conditions.","coverage":1},{"start":151.74,"end":155.14,"text":"Earth has exactly the right conditions for life.","coverage":1},{"start":155.74,"end":158.6,"text":"It is not too hot or too cold.","coverage":1},{"start":159.22,"end":160.16,"text":"It has water,","coverage":1},{"start":160.58,"end":160.98,"text":"air,","coverage":1},{"start":161.32,"end":162.38,"text":"and the right chemicals.","coverage":1},{"start":163.1,"end":168.66,"text":"I do not think that any other planets could have exactly the same conditions as Earth.","coverage":1},{"start":169.44,"end":169.96,"text":"Therefore,","coverage":1},{"start":170.5,"end":174.08,"text":"I do not think that there could be life on other planets.","coverage":1}],"file":"2f620357bbc134792c46.js","track":0,"media":"../assets/media/8a51f03a204efb0c83b9e8ff6fba679f57fd2ea4c59414540ab733feb95a9d97.mp3"}],"../assets/media/a94aaadefc0d40573c2e177d54d7110de501db7b7309c1e10fbfd6c3364540d6.mp3":[{"id":"PPT_a94aaadefc0d4057","audioId":"PPT_a94aaadefc0d4057","title":"Book 2 · Unit 8 · RW · READING 1","subtitle":"READING 1 · source slide 48","duration":259.89,"cues":[{"start":0,"end":2.7,"text":"the rise of commercial space travel,","coverage":1},{"start":3.78,"end":4.22,"text":"news,","coverage":1},{"start":5.42,"end":6.08,"text":"science,","coverage":1},{"start":7.26,"end":7.84,"text":"discoveries,","coverage":1},{"start":9.06,"end":9.76,"text":"technology,","coverage":1},{"start":10.94,"end":11.78,"text":"education,","coverage":1},{"start":12.92,"end":13.38,"text":"blogs,","coverage":1},{"start":14.62,"end":15.18,"text":"community.","coverage":1},{"start":16.18,"end":17.72,"text":"In 1957,","coverage":1},{"start":18.12,"end":22.04,"text":"the Soviet Union sent Sputnik one into space.","coverage":1},{"start":22.6,"end":26.76,"text":"It was the first successful spacecraft to orbit Earth,","coverage":1},{"start":27.34,"end":31.08,"text":"and it started the time period known as the Space Age.","coverage":1},{"start":31.88,"end":34.8,"text":"A short time later in the United States,","coverage":1},{"start":35.22,"end":38.18,"text":"the National Aeronautics and Space Administration,","coverage":1},{"start":38.5,"end":39,"text":"NASA,","coverage":1},{"start":39.68,"end":41.96,"text":"successfully sent another spacecraft,","coverage":1},{"start":42.58,"end":43.48,"text":"Explorer one,","coverage":1},{"start":43.88,"end":44.86,"text":"into space.","coverage":1},{"start":45.6,"end":47.04,"text":"In the years that followed,","coverage":1},{"start":47.88,"end":49.54,"text":"incredible advances were made.","coverage":1},{"start":50.32,"end":52.06,"text":"Astronauts orbited Earth,","coverage":1},{"start":52.46,"end":54.34,"text":"and men walked on the moon.","coverage":1},{"start":55.14,"end":56.54,"text":"The world, it seemed,","coverage":1},{"start":57,"end":59.84,"text":"wanted to learn what was beyond Earth.","coverage":1},{"start":60.9,"end":61.42,"text":"Today,","coverage":1},{"start":62.08,"end":63.94,"text":"space exploration continues,","coverage":1},{"start":64.54,"end":69.54,"text":"and governments still compete with one another to make new discoveries.","coverage":1},{"start":70.86,"end":72,"text":"In 2012,","coverage":1},{"start":72.68,"end":75.38,"text":"NASA landed its unmanned spacecraft,","coverage":1},{"start":75.68,"end":76.62,"text":"Curiosity,","coverage":1},{"start":77.08,"end":77.68,"text":"on Mars,","coverage":1},{"start":78.38,"end":81.42,"text":"in order to collect information about the planet.","coverage":1},{"start":82.5,"end":83.9,"text":"In 2016,","coverage":1},{"start":84.42,"end":89.36,"text":"Europe and Russia worked together and sent a spacecraft to Mars.","coverage":1},{"start":90.46,"end":94.6,"text":"China and India are also working on similar projects.","coverage":1},{"start":95.7,"end":96.16,"text":"However,","coverage":1},{"start":96.7,"end":99.22,"text":"there has been one big change.","coverage":1},{"start":99.9,"end":101.08,"text":"Private companies,","coverage":1},{"start":101.4,"end":104,"text":"instead of public government organizations,","coverage":1},{"start":104.54,"end":106.8,"text":"are entering the space race.","coverage":1},{"start":107.72,"end":112.44,"text":"SpaceX has been very successful in commercial space travel.","coverage":1},{"start":113.22,"end":120.66,"text":"They designed the spacecraft Dragon in order to deliver supplies to the International Space Station,","coverage":1},{"start":121.2,"end":121.78,"text":"ISS.","coverage":1},{"start":122.88,"end":123.94,"text":"In 2012,","coverage":1},{"start":124.62,"end":129.5,"text":"Dragon was the first commercial spacecraft in history to do that.","coverage":1},{"start":130.54,"end":131.28,"text":"Elon Musk,","coverage":1},{"start":131.64,"end":137.5,"text":"the man who started the company, has dreams that go beyond making deliveries.","coverage":1},{"start":138.4,"end":142.34,"text":"He hopes to build a base on Mars by 2028,","coverage":1},{"start":143.02,"end":148.74,"text":"and a one million person city there in the next 50 to 100 years.","coverage":1},{"start":150.32,"end":156.08,"text":"Another entrepreneur who supports commercial space travel is Sir Richard Branson.","coverage":1},{"start":156.96,"end":160.86,"text":"He started a private company called Virgin Galactic.","coverage":1},{"start":161.74,"end":165.3,"text":"Their goal is to open space travel to everyone.","coverage":1},{"start":166.3,"end":171.02,"text":"The company has sold about 700 future trips to space,","coverage":1},{"start":171.48,"end":177.14,"text":"some at the high cost of $450 ,000 per person.","coverage":1},{"start":178.32,"end":185.5,"text":"Those future space tourists come from countries all over the world and are all different ages.","coverage":1},{"start":186.42,"end":189.88,"text":"Private companies are lucky in one way.","coverage":1},{"start":190.48,"end":194.86,"text":"They don't have to wait for money from the government like NASA does.","coverage":1},{"start":195.66,"end":196.14,"text":"However,","coverage":1},{"start":196.56,"end":200.74,"text":"that doesn't mean that setbacks and accidents don't happen.","coverage":1},{"start":201.72,"end":203.06,"text":"In 2014,","coverage":1},{"start":203.68,"end":211.7,"text":"Virgin Galactic's VSS Enterprise crashed in the Mojave Desert in the United States during a test flight.","coverage":1},{"start":212.5,"end":214.6,"text":"The 39 -year -old pilot,","coverage":1},{"start":215.06,"end":216.9,"text":"Michael Alsbury, was killed.","coverage":1},{"start":217.8,"end":219.06,"text":"In 2023,","coverage":1},{"start":219.62,"end":226.98,"text":"the SpaceX spacecraft Starship exploded on its first flight after around two or three minutes.","coverage":1},{"start":227.86,"end":228.01,"text":"No","coverage":1},{"start":228.01,"end":233.5,"text":"one was hurt, and Elon Musk said they were going to try again in a few months.","coverage":1},{"start":234.4,"end":237.92,"text":"The race to explore the universe continues,","coverage":1},{"start":238.56,"end":241.02,"text":"and many private companies are competing.","coverage":1},{"start":241.88,"end":246.44,"text":"Some of those companies want to take people to the moon and back someday.","coverage":1},{"start":247.28,"end":249.78,"text":"Others want to take people to Mars.","coverage":1},{"start":250.68,"end":252.82,"text":"The possibilities are endless.","coverage":1},{"start":253.76,"end":255.1,"text":"Maybe in our lifetime,","coverage":1},{"start":255.74,"end":257.98,"text":"those dreams will come true.","coverage":1}],"file":"d00e9eea166dace87da9.js","track":0,"media":"../assets/media/a94aaadefc0d40573c2e177d54d7110de501db7b7309c1e10fbfd6c3364540d6.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1 How far is the moon from Earth? a 384,400 kilometres","slide":6,"shape":"12","bookPage":"170"},{"text":"2 How old is the moon? a 4.5 billion years","slide":6,"shape":"13","bookPage":"170"},{"text":"3 How hot can the moon get? b 120 °C","slide":7,"shape":"12","bookPage":"170"},{"text":"4 How cold can the moon get? b −250 °C","slide":7,"shape":"13","bookPage":"170"},{"text":"Possible answer: I was most surprised by the answers to Questions 3 and 4 because I did not think the moon could get so hot or cold.","slide":9,"shape":"9","bookPage":"170"},{"text":"1  An astronaut travels to and works in space.","slide":18,"shape":"8","bookPage":"170"},{"text":"2  A rocket is a vehicle for travelling in space.","slide":18,"shape":"9","bookPage":"170"},{"text":"3  The team’s main place to live and work is its base.","slide":18,"shape":"10","bookPage":"170"},{"text":"4  The fourth planet from the sun is Mars.","slide":18,"shape":"11","bookPage":"170"},{"text":"5  A difficult success is an achievement.","slide":18,"shape":"12","bookPage":"170"},{"text":"6  An important job that someone is sent to do is a mission.","slide":18,"shape":"13","bookPage":"170"},{"text":"1 The last time somebody went to the moon was in 2019. False: the last time was in 1972.","slide":22,"shape":"16","bookPage":"171"},{"text":"2 People who live on the moon will have to make their own water. True.","slide":22,"shape":"17","bookPage":"171"},{"text":"3 Technology from the Apollo missions is used to make furniture. True.","slide":22,"shape":"18","bookPage":"171"},{"text":"1 How many times did people go to the moon from 1969 to 1972? a six","slide":25,"shape":"16","bookPage":"171"},{"text":"2 How many astronauts can the Orion rocket carry? b six","slide":25,"shape":"17","bookPage":"171"},{"text":"3 How much will it cost to send people to the moon? a 93 billion dollars","slide":25,"shape":"18","bookPage":"171"},{"text":"1 The Artemis mission is going to build a base on the moon. T — true.","slide":27,"shape":"16","bookPage":"171"},{"text":"2 Jessica Watkins wants to live on Mars one day. F — Jessica Watkins hopes to stay at the moon base.","slide":27,"shape":"17","bookPage":"171"},{"text":"3 NASA wants to understand more about space travel. F — NASA wants to understand more about living on another planet.","slide":27,"shape":"18","bookPage":"171"},{"text":"1 NASA thinks that sending people to the moon is a good way to use money. Do you agree? Possible answer: I agree because learning about living in another place could be useful. However, I also think we should consider needs on Earth.","slide":29,"shape":"13","bookPage":"171"},{"text":"2 The speaker in the video says, “Many people say the Apollo missions are the biggest human achievement in technology.” Why do some people think this? Do you agree? Possible answer: Some people think this because Apollo technology contributed to many products. I agree that this is an important achievement.","slide":29,"shape":"14","bookPage":"171"},{"text":"e  beyond (prep) on the farther side of; at a farther distance than","slide":42,"shape":"7","bookPage":"172"},{"text":"f  crash (v) to be involved in an accident, especially in a vehicle","slide":42,"shape":"8","bookPage":"172"},{"text":"g  public (adj) related to money or services controlled or supplied by the government\nand not by a person or company","slide":42,"shape":"9","bookPage":"172"},{"text":"1 Who pays for space exploration? Possible answer: Governments and private companies pay for space exploration.","slide":44,"shape":"14","bookPage":"172"},{"text":"2 Would you like to go on holiday in space? Why / Why not? Possible answer: I would like to see Earth from space, but I would be worried about the cost and danger.","slide":44,"shape":"15","bookPage":"172"},{"text":"1 What is the Space Age? The time period that began when the first successful spacecraft orbited Earth.","slide":79,"shape":"13","bookPage":"174"},{"text":"2 What are countries competing with one another for? They are competing to make new discoveries.","slide":79,"shape":"14","bookPage":"174"},{"text":"3 What are some goals of future space travel? Some companies want to take people to the moon or Mars.","slide":80,"shape":"13","bookPage":"174"},{"text":"4 What is one difference between public and private companies? Private companies do not have to wait for government money in the way NASA does.","slide":80,"shape":"14","bookPage":"174"},{"text":"1 NASA sent Sputnik I into space, and it was the first successful spacecraft to orbit Earth. F — The Soviet Union sent Sputnik I into space.","slide":97,"shape":"13","bookPage":"174"},{"text":"2 Entrepreneurs like Elon Musk and Sir Richard Branson have to wait for government money to build new spacecraft. F — These entrepreneurs do not have to wait for government money.","slide":97,"shape":"14","bookPage":"174"},{"text":"3 In 2023, the SpaceX spacecraft Starship exploded on its first flight and killed its pilot. F — Starship exploded, but no one was hurt.","slide":97,"shape":"15","bookPage":"174"},{"text":"4 Virgin Galactic has sold about 700 future trips to space. T — true.","slide":98,"shape":"16","bookPage":"174"},{"text":"5 The first commercial spacecraft to deliver goods to the International Space Station was called Dragon. T — true.","slide":98,"shape":"17","bookPage":"174"},{"text":"1 The purpose of the text is to inform readers about the advances in commercial space travel.","slide":116,"shape":"16","bookPage":"174"},{"text":"2 You could find the text in a magazine.","slide":116,"shape":"17","bookPage":"174"},{"text":"3 The author is describing commercial space travel.","slide":116,"shape":"18","bookPage":"174"},{"text":"1. Summary gap 1\nAnswer: Friday","slide":119,"shape":"5","bookPage":null},{"text":"11. Paragraph A\nAnswer: vi","slide":119,"shape":"8","bookPage":null},{"text":"1 Do you ever wonder if people will live on another planet one day? a think about something and try to understand it b not believe something. a think about something and try to understand it.","slide":138,"shape":"12","bookPage":"176"},{"text":"2 It is important to support your ideas when you write an essay because it makes your arguments stronger. How can you do this? a think of more topics to write about b help show that something is true. b help show that something is true.","slide":138,"shape":"13","bookPage":"176"},{"text":"3 A lot of evidence shows that Mars has four seasons, like many places on Earth. Which is your favourite season? Why? a opinions that people have about a topic b information that makes you believe something is true. b information that makes you believe something is true.","slide":138,"shape":"14","bookPage":"176"},{"text":"4 Scientists have studied space for many years. Some think there is life on other planets, but nobody can prove it. What do you think? a show that something is true b ask questions about something. a show that something is true.","slide":139,"shape":"15","bookPage":"176"},{"text":"5 Life cannot exist without air and water. For this reason, Earth is the perfect planet for life. Could people live on a planet without air? How? a be real, alive or present b change and improve. a be real, alive or present.","slide":139,"shape":"16","bookPage":"176"},{"text":"6 The first space hotel plans to open in 2027. Because they will be so expensive, it is unlikely that many space hotels will open. Would you stay at a space hotel? Why / Why not? Who would you take with you? a expected to happen; probable b not expected to happen; not probable. b not expected to happen; not probable.","slide":139,"shape":"17","bookPage":"176"},{"text":"7 Astronauts have to train a lot to prepare for the conditions they will face in space, such as very hot temperatures. Would you like to be an astronaut? Why / Why not? a the location of something b the situation in which people live, work or do other things. b the situation in which people live, work or do other things.","slide":140,"shape":"15","bookPage":"176"},{"text":"8 On a particular night, for example, when the sky is clear, you can see the brightest planets when you look at the sky. Do you enjoy looking at the planets and stars at night? Why / Why not? a one thing or person and not any other b many different things or people, not just one. a one thing or person and not any other.","slide":140,"shape":"16","bookPage":"176"},{"text":"1 Do you ever wonder if people will live on another planet one day? Possible answer: I sometimes wonder whether people will live on Mars.","slide":141,"shape":"14","bookPage":"176"},{"text":"2 How can you support your ideas when you write an essay? Possible answer: I can give examples or information from reliable research.","slide":141,"shape":"15","bookPage":"176"},{"text":"3 Which is your favourite season? Why? Possible answer: I prefer spring because the weather is comfortable.","slide":142,"shape":"17","bookPage":"176"},{"text":"4 Scientists have studied space for many years. Some think there is life on other planets, but nobody can prove it. What do you think? Possible answer: I think it is possible, but I would need evidence before deciding.","slide":142,"shape":"18","bookPage":"176"},{"text":"5 Could people live on a planet without air? How? Possible answer: People would need equipment that supplies air.","slide":143,"shape":"16","bookPage":"176"},{"text":"6 Would you stay at a space hotel? Why / Why not? Who would you take with you? Possible answer: I would like to go with a friend, but only if I could afford it.","slide":143,"shape":"17","bookPage":"176"},{"text":"7 Would you like to be an astronaut? Why / Why not? Possible answer: I would enjoy the research, but I might find the conditions difficult.","slide":143,"shape":"18","bookPage":"176"},{"text":"8 Do you enjoy looking at the planets and stars at night? Why / Why not? Possible answer: I enjoy looking at stars because I find them interesting.","slide":143,"shape":"19","bookPage":"176"},{"text":"2 Skim the text on page 177. What type of text is it? a a story b an essay c a news article. b an essay.","slide":156,"shape":"11","bookPage":"176"},{"text":"1 It is true that the universe has thousands of solar systems and there are planets similar to Earth. a Experts have looked for signs of life on other planets. b Experts want to know how big the universe is. a Experts have looked for signs of life on other planets.","slide":166,"shape":"13","bookPage":"176"},{"text":"2 A planet needs very particular conditions to support life. a Technology can create water and air so that people can live. b It is not likely that other planets have the same environment as Earth. b It is not likely that other planets have the same environment as Earth.","slide":166,"shape":"14","bookPage":"176"},{"text":"1 How many solar systems are there in the universe? Thousands of solar systems.","slide":178,"shape":"13","bookPage":"176"},{"text":"2 What is the name of the telescope that discovered new planets? Kepler.","slide":178,"shape":"14","bookPage":"176"},{"text":"3 What is Kepler 22b? A planet.","slide":178,"shape":"15","bookPage":"176"},{"text":"4 Which university wrote a report saying that it is unlikely there is life on other planets? Princeton University.","slide":179,"shape":"16","bookPage":"176"},{"text":"5 What does the report say we need before we can know if there is life on other planets? Enough scientific evidence.","slide":179,"shape":"17","bookPage":"176"},{"text":"a Why, do you think, was Kepler 22b given that name? Possible answer: It was probably named after the Kepler telescope.","slide":190,"shape":"15","bookPage":"178"},{"text":"b Do you think the author thinks space exploration is a good idea? Why / Why not? Possible answer: The author may be doubtful about searching for life, because they stress the lack of evidence.","slide":190,"shape":"16","bookPage":"178"},{"text":"1  Some scientists believe that there must be life on other planets. O — opinion.","slide":192,"shape":"6","bookPage":"178"},{"text":"2  A number of scientists think that one of these planets has the right conditions to\nsupport life. F — fact.","slide":192,"shape":"7","bookPage":"178"},{"text":"3  It is unlikely that there is life on other planets. O — opinion.","slide":192,"shape":"8","bookPage":"178"},{"text":"1 What is the author’s main purpose? b to make readers agree with their opinion.","slide":205,"shape":"16","bookPage":"178"},{"text":"2 What does the author believe? b Life probably doesn’t exist on other planets.","slide":205,"shape":"17","bookPage":"178"},{"text":"3 Why does the author include information from a recent report from Princeton University? a to prove that experts agree with their opinion.","slide":205,"shape":"18","bookPage":"178"},{"text":"1 For many years, people have wondered whether we are the only living things in the universe. Some scientists believe that there must be life on other planets because the universe is so big.","slide":206,"shape":"7","bookPage":"177"},{"text":"1 However, it is unlikely that there is life on other planets because planets need a very specific environment for life to start. In the end, there are no facts that support the idea of life on other planets.","slide":207,"shape":"7","bookPage":"177"},{"text":"2 It is true that the universe has thousands of solar systems and there are planets similar to Earth. During its nine years in space, the very powerful Kepler telescope found more than 2,600 planets in orbit around stars. In fact, a number of scientists think that one of these planets, named Kepler 22b, has the right conditions – the right atmosphere and temperature – to support life.","slide":208,"shape":"7","bookPage":"177"},{"text":"2 However, there is no evidence that there is life on Kepler 22b. Experts argue that even with the best technology we can see no signs of life there. Until research shows us hard evidence, we cannot use Kepler 22b to support the idea of life on other planets.","slide":209,"shape":"7","bookPage":"177"},{"text":"3 A planet needs very particular conditions to support life. A planet with life would need to have water, the right temperature and the right mix of chemicals in the atmosphere. Earth has the perfect conditions for life, and it is very unlikely that another planet has exactly the same environment as Earth.","slide":210,"shape":"7","bookPage":"177"},{"text":"3 In addition, although some experts argue that life might exist on other planets, they have never found evidence to prove it.","slide":211,"shape":"7","bookPage":"177"},{"text":"3 A report from Princeton University suggests that it is highly unlikely that there is life on other planets. The researchers believe that we don’t have enough scientific evidence to decide if there is life on other planets. They say that just because conditions similar to Earth exist on other planets, it doesn’t mean that life exists there.","slide":212,"shape":"7","bookPage":"177"},{"text":"4 In conclusion, I do not believe that there is life on other planets. Although the universe is very big, a planet with life needs very special conditions.","slide":213,"shape":"7","bookPage":"177"},{"text":"4 Earth has exactly the right conditions for life. It is not too hot or too cold. It has water, air and the right chemicals. I do not think that any other planets could have exactly the same conditions as Earth. Therefore, I do not think that there could be life on other planets.","slide":214,"shape":"7","bookPage":"177"},{"text":"Paragraphs 1–2: Some scientists believe that there must be life on other planets because the universe is so big. A number of scientists think that one of these planets, named Kepler 22b, has the right conditions to support life. Experts argue that even with the best technology we can see no signs of life there.","slide":232,"shape":"16","bookPage":"179"},{"text":"Paragraph 3: Some experts argue that life might exist on other planets. A report from Princeton University suggests that it is highly unlikely that there is life on other planets. The researchers believe that we don’t have enough scientific evidence to decide if there is life on other planets.","slide":232,"shape":"17","bookPage":"179"},{"text":"Why does the author use the present simple? The author presents these as current views or general claims.","slide":232,"shape":"18","bookPage":"179"},{"text":"1 A report is a document that tells us about a subject in detail.","slide":234,"shape":"15","bookPage":"179"},{"text":"2 Research is the detailed investigation of a subject to discover new information or reach a new understanding.","slide":234,"shape":"16","bookPage":"179"},{"text":"3 To study is to examine a subject in detail to discover new information.","slide":234,"shape":"17","bookPage":"179"},{"text":"Some experts believe that there must be life on other planets because the universe is so big.","slide":236,"shape":"9","bookPage":"179"},{"text":"2 There are more than 100 billion stars in the Milky Way galaxy. (studies) Possible answer: Studies show that there are more than 100 billion stars in the Milky Way galaxy.","slide":239,"shape":"14","bookPage":"179"},{"text":"3 We need to study space. (scientists) Possible answer: Some scientists think that we need to study space.","slide":240,"shape":"13","bookPage":"179"},{"text":"4 Parts of Mars were once covered in ice. (reports) Possible answer: Reports suggest that parts of Mars were once covered in ice.","slide":240,"shape":"14","bookPage":"179"},{"text":"The evidence supports this explanation.","slide":244,"shape":"6","bookPage":null},{"text":"The results suggest a possible answer.","slide":244,"shape":"9","bookPage":null},{"text":"The class tested two model designs. One of those designs stood upright more easily. That result supported the choice of a wider base.","slide":245,"shape":"6","bookPage":null},{"text":"Mia supports the museum visit. She believes the models will help beginners. Her reason explains why she prefers that visit.","slide":246,"shape":"6","bookPage":null},{"text":"A teacher is showing a round model to four students. Other models are arranged on the table.","slide":247,"shape":"7","bookPage":null},{"text":"A student could study the marks on the large model. They could compare those marks with a photograph.","slide":247,"shape":"10","bookPage":null},{"text":"1. The club wanted all town lights switched off.\nAnswer: FALSE","slide":252,"shape":"5","bookPage":null},{"text":"11. An alternative activity is ready when the sky cannot be seen.\nAnswer: D","slide":252,"shape":"8","bookPage":null},{"text":"1. Summary gap 1\nAnswer: island","slide":255,"shape":"5","bookPage":null},{"text":"11. Paragraph A\nAnswer: i","slide":255,"shape":"8","bookPage":null},{"text":"These results support the group’s suggestion.","slide":263,"shape":"6","bookPage":null},{"text":"The report suggests a shorter demonstration.","slide":263,"shape":"9","bookPage":null},{"text":"The group asked ten visitors to choose a display. Seven of those visitors chose the model. That result suggests the model was popular within this small group.","slide":264,"shape":"6","bookPage":null},{"text":"The class compared two instruction cards. Students made fewer mistakes with the second card. This result supports using that clearer version.","slide":265,"shape":"6","bookPage":null},{"text":"A student is comparing printed space pictures at a library table. A laptop is open beside her. She may be gathering information for a report.","slide":266,"shape":"7","bookPage":null},{"text":"The student could note where each picture came from. She could compare the accompanying explanation with another source. This would help her check the evidence before using it.","slide":267,"shape":"7","bookPage":null},{"text":"1 Look back at paragraph 1 of Reading 2 on page 177. What is the author’s main argument? Possible answer: It is unlikely that there is life on other planets.","slide":279,"shape":"11","bookPage":"180"},{"text":"What reasons support the author’s argument? Paragraph 2: there are no signs of life on Kepler 22b. Paragraph 3: life needs particular conditions and no evidence of life elsewhere has been found.","slide":281,"shape":"14","bookPage":"180"},{"text":"Source a — The International Space Agency: Governments around the world should spend more money on space programmes. The International Space Station (ISS) is a good example why. The ISS has existed since 1998 and brings together many countries. Astronauts live in space and take part in important experiments.","slide":283,"shape":"19","bookPage":"181"},{"text":"Source a — The International Space Agency: The ISS cost about $100 billion and one country could not pay for that on its own. International space exploration proves that countries can work together. It represents the spirit of partnership. With so much war in the world, governments should spend more money on things they can achieve together. Maybe that will help bring peace.","slide":293,"shape":"19","bookPage":"181"},{"text":"Source b — A newspaper editorial: More money should be spent on people who need clean water and food, on access to education and on medical research.","slide":294,"shape":"20","bookPage":"181"},{"text":"Source b — A newspaper editorial: For example, a Japanese study found that a drug made from sea sponges helps treat several types of cancer. And yet 90% of the Earth's oceans are still unexplored. The ocean is a valuable resource. Governments should spend more money on ocean exploration than on space exploration.","slide":295,"shape":"19","bookPage":"181"},{"text":"Source c — A government agency: Uncovering the mysteries of space is a huge task that should continue to be funded. Imagine the discoveries and advances in technology that will be made as countries go farther and farther into space, especially in the race to be the first to Mars.","slide":295,"shape":"20","bookPage":"181"},{"text":"Source c — A government agency: Medical advances are also made as a result of sending humans to space. For example, when astronauts are in space, their bones become weaker and more likely to break. Many elderly people also have weak bones. Drugs that can help elderly people can be tested on astronauts in space. Research done in space can improve life on Earth. Governments should absolutely spend more money on space programmes.","slide":296,"shape":"20","bookPage":"181"},{"text":"For\nAgainst\nThe ISS brings many countries together (a).\nSpace exploration is expensive (b).\nAstronauts take part in important experiments (a).\nSpace travel is dangerous (b).\nThis research is necessary for long-term journeys, such as travel to Mars (a).\n","slide":299,"shape":"12","bookPage":"182"},{"text":"For\nAgainst\nSpace exploration proves that countries can work together (a).\nBuilding spacecraft wastes natural resources (b).\nIt leads to technological advances (c).\nThe money should support clean water, food, education and medical research (b).\nPeople may need to live on Mars because Earth will become too hot and crowded (c).\n","slide":300,"shape":"12","bookPage":"182"},{"text":"For\nAgainst\nIt encourages young people to study Science and Engineering (c).\n\nIt leads to medical advances (c).\n\nResearch in space can improve life on Earth (c).\n","slide":301,"shape":"12","bookPage":"182"},{"text":"Possible answer: I think medical research is a strong argument because it connects space exploration with a clear benefit for people on Earth. Source c gives an example involving weak bones. I would also want evidence showing how useful the research has been.","slide":304,"shape":"9","bookPage":"182"},{"text":"Think of information to support the arguments you chose in Exercise 5. Possible support: Source a describes countries working together on the ISS.","slide":306,"shape":"17","bookPage":"182"},{"text":"Think of information to support the arguments you chose in Exercise 5. Possible support: Source c gives the example of studying weak bones in astronauts.","slide":306,"shape":"18","bookPage":"182"},{"text":"Think of information to support the arguments you chose in Exercise 5. Possible support: Source b lists clean water, food, education and medical research.","slide":306,"shape":"19","bookPage":"182"},{"text":"Possible answer: I agree more with b because governments have many needs to meet on Earth. Space research can be valuable, but I would give priority to clean water, education and health care before increasing space budgets.","slide":308,"shape":"9","bookPage":"182"},{"text":"Some experts believe that space travel will become cheaper in the future.","slide":319,"shape":"10","bookPage":"183"},{"text":"Possible answer: The scientist says that some researchers disagree because there is no evidence of running water.","slide":322,"shape":"14","bookPage":"184"},{"text":"Possible answer: The scientist thinks that space tourism will happen soon but will be too expensive for most people.","slide":322,"shape":"15","bookPage":"184"},{"text":"1 What are some of the dangers of space exploration, especially for astronauts? Possible answer: I think that accidents are a serious danger for astronauts.","slide":324,"shape":"13","bookPage":"184"},{"text":"2 How would the discovery of life on another planet affect life on Earth? Possible answer: I think that finding life elsewhere would change how we understand the universe, but my partner disagrees. She suggests that most people’s daily lives would stay the same.","slide":324,"shape":"14","bookPage":"184"},{"text":"1 We build rockets (in order) to send people into space.","slide":327,"shape":"12","bookPage":"184"},{"text":"2 We wanted to land on the moon (in order) to explore it in more detail.","slide":327,"shape":"13","bookPage":"184"},{"text":"1 Europe and Russia worked together order to send a spacecraft to Mars. Corrected sentence: Europe and Russia worked together in order to send a spacecraft to Mars.","slide":329,"shape":"13","bookPage":"184"},{"text":"2 Tourists will have to spend a lot of money for to buy a ticket to space. Corrected sentence: Tourists will have to spend a lot of money to buy a ticket to space.","slide":329,"shape":"14","bookPage":"184"},{"text":"6 Complete the sentence using an infinitive of purpose. We explore space in order to learn more about the universe.","slide":331,"shape":"9","bookPage":"185"},{"text":"2 Write sentences linking the reason and result with because and so. I visited NASA because I wanted to see moon rocks. I wanted to see moon rocks, so I visited NASA.","slide":338,"shape":"12","bookPage":"185"},{"text":"3 Write sentences linking the reason and result with because and so. I’m studying Engineering because I want to design spaceships. I want to design spaceships, so I’m studying Engineering.","slide":339,"shape":"12","bookPage":"185"},{"text":"4 Write sentences linking the reason and result with because and so. I bought a telescope because I like looking at the stars and planets. I like looking at the stars and planets, so I bought a telescope.","slide":340,"shape":"12","bookPage":"185"},{"text":"5 Write sentences linking the reason and result with because and so. I’m studying Business because I would like to be an entrepreneur. I would like to be an entrepreneur, so I’m studying Business.","slide":341,"shape":"12","bookPage":"185"},{"text":"The introductory paragraph is the first paragraph in an essay.","slide":343,"shape":"13","bookPage":"186"},{"text":"The body is the middle paragraph or set of paragraphs of the essay.","slide":343,"shape":"14","bookPage":"186"},{"text":"The body can be one paragraph or many paragraphs.","slide":344,"shape":"13","bookPage":"186"},{"text":"The concluding paragraph is the last paragraph in an essay.","slide":344,"shape":"14","bookPage":"186"},{"text":"Essay structure: The introduction gives background and states the thesis. The two body paragraphs use reasons, examples and references to support the argument. The conclusion retells the main points and states the writer’s opinion again.","slide":355,"shape":"15","bookPage":"186"},{"text":"We use simple models to explain complex ideas.","slide":359,"shape":"6","bookPage":null},{"text":"Some students believe that the visit is worthwhile.","slide":359,"shape":"9","bookPage":null},{"text":"The club should provide a picture guide for beginners. The practice feedback shows that several students misunderstood the written steps. Pictures beside those steps could make the task clearer.","slide":360,"shape":"6","bookPage":null},{"text":"The class built a model to explain the station’s parts. Visitors could point to those parts while asking questions. As a result, the discussion focused on specific details.","slide":361,"shape":"6","bookPage":null},{"text":"I believe that a space exhibition visit could help this class. Students could examine models to understand unfamiliar objects. For example, they could compare a model with a labelled photograph. This would give them a specific detail to discuss afterwards.","slide":362,"shape":"7","bookPage":null},{"text":"The class should collect information about cost and available activities. I believe that both factors matter for this decision. Students could compare two exhibitions to find a suitable option. Their choice would then have a clear practical reason.","slide":363,"shape":"7","bookPage":null}];
